		/**
		* 手写的 fileStash 客户端调用描述符。
		* wire 字段名 = 宿主方法参数名(cwd/sessionId/name/dataBase64/relPath);
		* $mount 时用 strict zod schema 做边界校验,与宿主实现一一对应。
		*/
		const stringParameter = (name, typeSymbol) => ({
			name,
			wire: name,
			source: "json",
			codec: {
				mode: "strict",
				typeSymbol,
				schema: string()
			}
		});
		const resultCodec = (symbol, schema) => ({
			mode: "strict",
			typeSymbol: symbol,
			schema
		});
